test('atomic imports preserve configured deadlines across persistence and priority changes', (t) => {
  const file = dataFile(t);
  const clock = manualClock();
  const persistence = createPersistence(file);
  const store = TicketStore.open({ clock, persistence, dueTimes: true, dueHours: { urgent: 2 } });
  const [id] = store.importTickets([ticketBody({ priority: 'urgent' })], 'agent');
  const ticket = store.get(id);
  assert.equal(Date.parse(ticket.due) - Date.parse(ticket.created), 2 * HOUR);
  assert.equal(ticket.assignee, null);
  store.assign(id, 'dana', 'agent');
  store.update(id, { priority: 'low' }, 'agent');
  const reopened = TicketStore.open({ clock, persistence, dueTimes: true, dueHours: { urgent: 7 } });
